import { ref, computed } from 'vue';
import { approval_history } from 'src/constants';

const WIDE_PANELS = [
  'activity_stream',
  approval_history,
  'expert_mode',
  'support',
  'extraction_insights',
  'validation_assistant',
];

export function useSidebarPanel() {
  const current_sidebar = ref('');

  const sidebarWidthClass = computed(() => {
    if (current_sidebar.value === '') return '';
    return WIDE_PANELS.includes(current_sidebar.value)
      ? 'sidebar-panel-wide'
      : 'sidebar-panel-width';
  });

  const rightSectionClass = computed(() => {
    if (current_sidebar.value === '') return 'full-width';
    return WIDE_PANELS.includes(current_sidebar.value)
      ? 'right_section_25vw'
      : 'right_section_sidebar';
  });

  function toggleSideBar(name: string) {
    if (current_sidebar.value === name) {
      current_sidebar.value = '';
      return;
    }

    current_sidebar.value = name;
  }

  return {
    current_sidebar,
    sidebarWidthClass,
    rightSectionClass,
    toggleSideBar,
    WIDE_PANELS,
  };
}
